gold = Image.open('/opt/exam/grader/golden.png').convert('L')
cap = Image.open('/var/exam/capture.png').convert('L')

# In cap, bores are dark circles (pixel value < 50)
c_pix = cap.load()
c_bores = []
for y in range(120, 230):
    for x in range(160, 330):
        if c_pix[x, y] < 80:
            c_bores.append((x, y))

# In gold, pins are white/bright circles (pixel value > 220) with shadows
g_pix = gold.load()
g_pins = []
for y in range(120, 230):
    for x in range(160, 330):
        if g_pix[x, y] > 220:
            g_pins.append((x, y))

print('cap bore points count:', len(c_bores))
print('gold pin points count:', len(g_pins))

# Group c_bores into 4 clusters:
from collections import defaultdict
def cluster(pts):
    # simple 4-quadrant or kmeans
    # let's find the 4 centers
    clusters = []
    for p in pts:
        matched = False
        for c in clusters:
            cx = sum(x for x, y in c) / len(c)
            cy = sum(y for x, y in c) / len(c)
            if (p[0] - cx)**2 + (p[1] - cy)**2 < 20**2:
                c.append(p)
                matched = True
                break
        if not matched:
            clusters.append([p])
    centers = [(sum(x for x, y in c)/len(c), sum(y for x, y in c)/len(c)) for c in clusters if len(c) > 5]
    return sorted(centers)

print('cap bore centers:', cluster(c_bores))
print('gold pin centers:', cluster(g_pins))
""}

